int SNC = MAXN-2;

typedef ll tf;const tf INFFLUJO=1e14;
typedef ll tc;const tc INFCOSTO=1e14;

struct edge {
	int u,v; tf cap, flow; tc cost;
	tf remaining() { return cap - flow; }
};

int total_nodes=MAXN;
vector<int> graph[MAXN];
vector<edge> edges;

void add_edge(int u, int v, tf capacity, tc cost_value) {
	if (DEBUG) {
		string dem=to_string(u), pen=to_string(v);
		if (u==SRC) dem="SRC";
