	}
	graph[u].push_back(edges.size()); edges.push_back({u,v,capacity,0,cost_value});
	graph[v].push_back(edges.size()); edges.push_back({v,u,0,0,-cost_value});
}

ll dist[MAXN], min_cost;
int predecessor[MAXN];
tf capacity[MAXN], max_flow;
bool in_queue[MAXN];

void run_flow(int s, int t) {
	memset(in_queue, 0, sizeof(in_queue));
	max_flow=0; min_cost=0;
	while (true) {
		fill(dist, dist+total_nodes, INFCOSTO);
		dist[s]=0;
		memset(predecess,-1,sizeof(predecess));
		predecess[s]=0;
		memset(capacity,0,sizeof(capacity));
		capacity[s]=INFFLUJO;
		std::queue<int> q; q.push(s); in_queue[s]=true;
		while (!q.empty()) {
			int u=q.front(); q.pop(); in_queue[u]=false;
			for (auto i : graph[u]) {
				auto &E=edges[i];
				if (E.remaining() && dist[E.v]>dist[u]+E.cost+1e-9) {
					dist[E.v]=dist[u]+E.cost;
					predecess[E.v]=i;
					capacity[E.v]=min(capacity[u], E.remaining());
					if (!in_queue[E.v]) q.push(E.v), in_queue[E.v]=true;
				}
			}
		}
		if (predecess[t]<0) break;
		max_flow+=capacity[t];
		min_cost+=capacity[t]*dist[t];
		for (int v=t; v!=s; v=edges[predecess[v]].u) {
			edges[predecess[v]].flow+=capacity[t];
			edges[predecess[v]^1].flow-=capacity[t];
		}
	}
}

