		for_range(j,0,MAXT-1) for_range(K,1,k+1) {
			add_edge(x*MAXT+j, y*MAXT+j+1, 1, c+d*(2*K-1));
		}
		for_range(j,0,MAXT-1) for_range(K,1,k+1) {
			add_edge(y*MAXT+j, x*MAXT+j+1, 1, c+d*(2*K-1));
		}
	}
	for_range(i,0,n) {
		for_range(j,0,MAXT-1) for_range(K,1,k+1) {
			add_edge(i*MAXT+j, i*MAXT+j+1, 1, c);
		}
	}
	run_flow(SRC, SNC);
	if (DEBUG) cout<<"mincost: "<<min_cost<<" maxflow: "<<max_flow<<endl;
	cout<<min_cost<<endl;
